SELECT 

WHERE rv.ORDER_ID = #{orderId}
ORDER BY rv.RES_ID

SELECT * FROM (
    SELECT t.*, ROWNUM rn FROM (
        SELECT , o.ORDER_NO, c.CUST_NAME

        WHERE 1 = 1

            AND (o.ORDER_NO LIKE '%' || #{keyword} || '%' OR c.CUST_NAME LIKE '%' || #{keyword} || '%')

         AND rv.RES_STATUS = #{status} 
         AND rv.EXPECT_IN  >= #{startDate} 
         AND rv.EXPECT_IN  <  #{endDate}   
        ORDER BY rv.RES_ID DESC
    ) t WHERE ROWNUM <= #{offset} + #{limit}
) WHERE rn > #{offset}

SELECT COUNT(1)
  FROM RESERVATION rv
  LEFT JOIN HOTEL_ORDER o ON rv.ORDER_ID = o.ORDER_ID
  LEFT JOIN CUSTOMER c ON o.CUSTOMER_ID = c.CUSTOMER_ID
WHERE 1 = 1

    AND (o.ORDER_NO LIKE '%' || #{keyword} || '%' OR c.CUST_NAME LIKE '%' || #{keyword} || '%')

 AND rv.RES_STATUS = #{status} 
 AND rv.EXPECT_IN  >= #{startDate} 
 AND rv.EXPECT_IN  <  #{endDate}

mapper.update:
UPDATE RESERVATION SET
    RES_STATUS = #{status},
    VERSION = VERSION + 1,
    UPDATE_TIME = F_NOW(),
    UPDATE_BY = #{updateBy}
WHERE RES_ID = #{resId} AND VERSION = #{version}
